AssistantMessageToolRequest(name='create', tool_call_id='function-call-9442e3f9-fb25-4b89-9bc6-70b8b37a5977', arguments={'file_text': 'document.addEventListener('DOMContentLoaded', () => {
    const addToCartButtons = document.querySelectorAll('.add-to-cart');
    const liveAnnouncer = document.getElementById('live-announcer');

    addToCartButtons.forEach(button => {
        button.addEventListener('click', (e) => {
            e.preventDefault();

            const productCard = button.closest('.product-card');
            const productName = productCard.querySelector('.product-title').textContent;

            if (liveAnnouncer) {
                liveAnnouncer.textContent = `${productName} added to cart.`;

                setTimeout(() => {
                    if (liveAnnouncer.textContent === `${productName} added to cart.`) {
                        liveAnnouncer.textContent = '';
                    }
                }, 3000);
            }

            const originalText = button.textContent;
            button.textContent = 'Added!';
            button.style.backgroundColor = 'var(--color-primary)';
            button.style.color = 'var(--color-primary-text)';

            setTimeout(() => {
                button.textContent = originalText;
                button.style.backgroundColor = '';
                button.style.color = '';
            }, 2000);
        });
    });

    const mobileMenuToggle = document.querySelector('.mobile-menu-toggle');

    if (mobileMenuToggle) {
        mobileMenuToggle.addEventListener('click', () => {
            const isExpanded = mobileMenuToggle.getAttribute('aria-expanded') === 'true';
            mobileMenuToggle.setAttribute('aria-expanded', !isExpanded);

            if (!isExpanded) {
                if (liveAnnouncer) liveAnnouncer.textContent = "Mobile menu opened";
            } else {
                if (liveAnnouncer) liveAnnouncer.textContent = "Mobile menu closed";
            }
        });
    }
});
